"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Progress: generated by UIX from the design system. Same variants and sizes as the Figma component.

const progressVariants = cva(
  "h-2 w-full overflow-hidden bg-muted rounded-full",
);

export interface ProgressProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof progressVariants> {
  /** 0 to 100. */
  value?: number;
}

const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(
  ({ className, value = 0, ...props }, ref) => {
    const percent = Math.min(100, Math.max(0, value));
    return (
      <div data-slot="progress" data-kind="track" ref={ref} role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent} className={cn(progressVariants({  }), className)} {...props}>
        <div className="h-full rounded-[inherit] transition-[width] bg-brand" style={{ width: percent + "%" }} />
      </div>
    );
  },
);
Progress.displayName = "Progress";

export { Progress, progressVariants };
